package com.fakenewsdetector.security;
import com.fakenewsdetector.entity.User; import com.fakenewsdetector.repository.UserRepository; import io.jsonwebtoken.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; private final UserRepository users; public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{Claims c=jwt.parse(h.substring(7)); Long id=Long.valueOf(c.getSubject()); User u=users.findById(id).orElse(null); if(u!=null){var auth=new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())));SecurityContextHolder.getContext().setAuthentication(auth);}}catch(JwtException|IllegalArgumentException ignored){} chain.doFilter(req,res,chain);}
}
